    "source": "/** Segment tree (point assign + range sum), teaching version. 0-based, half-open [l, r). */\npublic class SegTree {\n    int n;\n    long[] tree; // tree[node] = sum of a[lo, hi); node 1 is the root\n\n    SegTree(long[] a) {\n        n = a.length;\n        tree = new long[4 * Math.max(1, n)];\n        if (n > 0) build(a, 1, 0, n);\n    }\n\n    void build(long[] a, int node, int lo, int hi) {\n        if (hi - lo == 1) {\n            tree[node] = a[lo];\n            return;\n        }\n        int mid = lo + (hi - lo) / 2;\n        build(a, 2 * node, lo, mid);\n        build(a, 2 * node + 1, mid, hi);\n        tree[node] = tree[2 * node] + tree[2 * node + 1];\n    }\n\n    /** a[i] = v */\n    void set(int i, long v) {\n        setRec(1, 0, n, i, v);\n    }\n\n    void setRec(int node, int lo, int hi, int i, long v) {\n        if (hi - lo == 1) {\n            tree[node] = v;\n            return;\n        }\n        int mid = lo + (hi - lo) / 2;\n        if (i < mid) setRec(2 * node, lo, mid, i, v);\n        else setRec(2 * node + 1, mid, hi, i, v);\n        tree[node] = tree[2 * node] + tree[2 * node + 1];\n    }\n\n    /** Sum of a[l..r). */\n    long sum(int l, int r) {\n        return query(1, 0, n, l, r);\n    }\n\n    long query(int node, int lo, int hi, int l, int r) {\n        if (r <= lo || hi <= l) return 0;\n        if (l <= lo && hi <= r) return tree[node];\n        int mid = lo + (hi - lo) / 2;\n        return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid, hi, l, r);\n    }\n}\n",
