    "source": "// Segment tree (point assign + range sum), teaching version. 0-based, half-open [l, r).\npub struct SegTree {\n    pub n: usize,\n    pub tree: Vec<i64>, // tree[node] = sum of a[lo, hi); node 1 is the root\n}\n\nimpl SegTree {\n    pub fn new(a: &[i64]) -> Self {\n        let n = a.len();\n        let mut t = SegTree { n, tree: vec![0; 4 * n.max(1)] };\n        if n > 0 {\n            t.build(a, 1, 0, n);\n        }\n        t\n    }\n\n    fn build(&mut self, a: &[i64], node: usize, lo: usize, hi: usize) {\n        if hi - lo == 1 {\n            self.tree[node] = a[lo];\n            return;\n        }\n        let mid = lo + (hi - lo) / 2;\n        self.build(a, 2 * node, lo, mid);\n        self.build(a, 2 * node + 1, mid, hi);\n        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1];\n    }\n\n    /// a[i] = v\n    pub fn set(&mut self, i: usize, v: i64) {\n        let n = self.n;\n        self.set_rec(1, 0, n, i, v);\n    }\n\n    fn set_rec(&mut self, node: usize, lo: usize, hi: usize, i: usize, v: i64) {\n        if hi - lo == 1 {\n            self.tree[node] = v;\n            return;\n        }\n        let mid = lo + (hi - lo) / 2;\n        if i < mid { self.set_rec(2 * node, lo, mid, i, v) }\n        else { self.set_rec(2 * node + 1, mid, hi, i, v) }\n        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1];\n    }\n\n    /// Sum of a[l..r).\n    pub fn sum(&self, l: usize, r: usize) -> i64 {\n        self.query(1, 0, self.n, l, r)\n    }\n\n    fn query(&self, node: usize, lo: usize, hi: usize, l: usize, r: usize) -> i64 {\n        if r <= lo || hi <= l { return 0; }\n        if l <= lo && hi <= r { return self.tree[node]; }\n        let mid = lo + (hi - lo) / 2;\n        self.query(2 * node, lo, mid, l, r) + self.query(2 * node + 1, mid, hi, l, r)\n    }\n}\n",
